import{_ as s,o as c,a as t,b as e}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"访存函数","link":"/api/SIMT-API/memory_access_functions/memory_access_functions"},{"text":"访存函数简介","link":"/api/SIMT-API/memory_access_functions/memory_access_functions_intro"}]},"headers":[],"relativePath":"api/SIMT-API/memory_access_functions/memory_access_functions_intro.md","filePath":"api/SIMT-API/memory_access_functions/memory_access_functions_intro.md","outlineHeaders":[{"level":2,"title":"基本概念","slug":"基本概念","link":"#基本概念"},{"level":2,"title":"API列表","slug":"API列表","link":"#API列表"},{"level":2,"title":"接口选择","slug":"接口选择","link":"#接口选择"},{"level":3,"title":"加载路径选择","slug":"加载路径选择","link":"#加载路径选择"},{"level":3,"title":"存储路径选择","slug":"存储路径选择","link":"#存储路径选择"},{"level":3,"title":"Cache一致性维护","slug":"Cache一致性维护","link":"#Cache一致性维护"},{"level":2,"title":"使用建议","slug":"使用建议","link":"#使用建议"}],"lastUpdated":1785986301000}'),l={name:"api/SIMT-API/memory_access_functions/memory_access_functions_intro.md"};function n(d,a,p,h,o,i){return c(),t("div",null,[...a[0]||(a[0]=[e(`<div><article class="markdown-body"><h1>访存函数简介</h1><p>SIMT编程通常需要大量Thread并行访问Global Memory。访存函数用于显式控制Global Memory访问时的缓存路径和缓存一致性维护方式，帮助开发者根据数据复用特征、写回方式和跨核可见性要求选择合适的加载、存储或Cache刷新接口。</p><p>参考通用SIMT编程经验，同一Warp内线程访问连续、对齐的Global Memory地址时，通常更有利于形成高效访存；访存地址离散、未对齐或频繁跨Cache Line访问时，可能增加访存事务数量并降低吞吐。开发者应结合数据布局、访问模式和缓存复用情况选择访存接口。</p><h2 id="基本概念">基本概念<a class="header-anchor" href="#基本概念">​</a></h2><table><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>Global Memory</td><td>所有Thread均可访问的全局内存空间，是访存函数的主要访问对象。</td></tr><tr><td>L2 Cache</td><td>Global Memory访问路径上的缓存层级，可缓存从Global Memory读取或写入的数据。</td></tr><tr><td>Data Cache</td><td>SIMT线程访问Global Memory时使用的缓存空间，适合存在局部复用的数据访问。</td></tr><tr><td>Cache Line</td><td>Cache维护和刷新时的基本粒度。<code>asc_dcci_single</code>接口用于刷新指定地址所在的Cache Line。</td></tr></tbody></table><h2 id="API列表">API列表<a class="header-anchor" href="#API列表">​</a></h2><table><thead><tr><th>类别</th><th>接口名</th><th>功能说明</th></tr></thead><tbody><tr><td>加载函数</td><td><a href="asc_ldcg.html">asc_ldcg</a></td><td>从L2 Cache加载数据；未命中时从Global Memory读取，并缓存到L2 Cache。</td></tr><tr><td>加载函数</td><td><a href="asc_ldca.html">asc_ldca</a></td><td>优先从Data Cache加载数据；未命中时尝试从L2 Cache或Global Memory读取，并缓存到L2 Cache和Data Cache。</td></tr><tr><td>存储函数</td><td><a href="asc_stcg.html">asc_stcg</a></td><td>将数据存储到Global Memory，并缓存到L2 Cache，不缓存到Data Cache。</td></tr><tr><td>存储函数</td><td><a href="asc_stwt.html">asc_stwt</a></td><td>将数据存储到Global Memory，并缓存到Data Cache和L2 Cache。</td></tr><tr><td>Cache刷新函数</td><td><a href="asc_dcci_single.html">asc_dcci_single</a></td><td>刷新指定地址所在的Cache Line，保证后续读取时Cache一致性。</td></tr><tr><td>Cache刷新函数</td><td><a href="asc_dcci_entire.html">asc_dcci_entire</a></td><td>刷新核内整个Data Cache，保证后续读取时Cache一致性。该接口开销较大，性能敏感场景慎用。</td></tr><tr><td>空操作函数</td><td><a href="asc_nop.html">asc_nop</a></td><td>生成一条空操作指令，占用当前线程15个时钟周期，但不执行任何实际计算与访存操作。</td></tr></tbody></table><h2 id="接口选择">接口选择<a class="header-anchor" href="#接口选择">​</a></h2><h3 id="加载路径选择">加载路径选择<a class="header-anchor" href="#加载路径选择">​</a></h3><p>当数据存在局部复用，且后续仍可能由当前线程或当前核再次访问时，可以考虑使用<code>asc_ldca</code>，使数据同时进入Data Cache和L2 Cache。若数据主要依赖L2 Cache，或希望避免写入Data Cache，可使用<code>asc_ldcg</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">float</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_ldca</span><span class="p">(</span><span class="n">input</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">idx</span><span class="p">);</span>
</code></pre></div><h3 id="存储路径选择">存储路径选择<a class="header-anchor" href="#存储路径选择">​</a></h3><p><code>asc_stcg</code>会将数据写入Global Memory并缓存到L2 Cache，不缓存至Data Cache；<code>asc_stwt</code>会将数据写入Global Memory，并缓存至Data Cache和L2 Cache。若写入后的数据可能很快被当前核再次读取，可根据访问复用情况选择<code>asc_stwt</code>；若不希望污染Data Cache，可考虑<code>asc_stcg</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_stcg</span><span class="p">(</span><span class="n">output</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">idx</span><span class="p">,</span><span class="w"> </span><span class="n">value</span><span class="p">);</span>
</code></pre></div><h3 id="Cache一致性维护">Cache一致性维护<a class="header-anchor" href="#Cache一致性维护">​</a></h3><p>SIMT程序中，写入数据时会立即写入Global Memory，使其他核可见。当从Global Memory读取的数据可能已被其他核修改时，可以使用DCCI类接口刷新Data Cache，以获取Global Memory中的最新数据。</p><p><code>asc_dcci_single</code>只刷新指定地址所在的Cache Line，适合轮询标志位等小范围刷新场景；<code>asc_dcci_entire</code>刷新整个Data Cache，开销较大，应仅在确实需要全量刷新时使用。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">while</span><span class="w"> </span><span class="p">(</span><span class="n">flag</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="mi">1U</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">asc_dcci_single</span><span class="p">(</span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">void</span><span class="w"> </span><span class="o">*&gt;</span><span class="p">(</span><span class="n">flag</span><span class="p">));</span>
<span class="p">}</span>
</code></pre></div><h2 id="使用建议">使用建议<a class="header-anchor" href="#使用建议">​</a></h2><ul><li>优先让同一Warp内相邻Thread访问连续、对齐的Global Memory地址，以提升访存效率。</li><li>对连续且对齐的数据，可结合接口支持的数据类型选择<code>float2</code>、<code>float4</code>、<code>int2</code>、<code>int4</code>等向量类型，减少单线程访存指令数量。</li><li>根据数据复用情况选择加载和存储路径，避免不必要地占用Data Cache。</li><li>跨Thread Block或跨核通过Global Memory传递数据和标志时，需要结合<a href="../sync_and_memory_fence/sync_and_memory_fence.html">同步与内存栅栏</a>、<a href="../atomic_operations/atomic_operations.html">原子操作</a>和DCCI类接口设计同步协议。</li><li>DCCI类接口用于处理Cache一致性问题，不等价于线程同步接口，也不能替代原子操作。</li><li><code>asc_nop</code>主要用于避免多个线程读写同地址情况下可能发生的卡死问题。</li></ul></article></div>`,1)])])}const m=s(l,[["render",n]]);export{_ as __pageData,m as default};
